/**
 * Ends the XMP document by writing the following footer and
 * clearing the namespace mappings:
 * <pre>
 * &lt;/rdf:RDF&gt;
 * </pre>
 */
@Override
public void endDocument() throws SAXException {
    endElement(RDF, "RDF", "rdf:RDF");
    endPrefixMapping("xmp");
    endPrefixMapping("rdf");
    super.endDocument();
}
